contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entrypoint for the property test.
    // Params:
    // - addr: arbitrary address used for proposals
    // - amount: arbitrary uint used for grant amount
    // - proposalIDOffset: used to select which created proposal to call finaliseProposal on
    // We create a proposal, try to trigger finalising and then attempt to finaliseProposal.
    function run(address addr, uint amount, uint proposalIDOffset) public payable {
        require(true);

        // Initialize c (only allowed once). Use this contract as VADER, USDV, VAULT placeholders.
        // init has require(inited == false) so this first call will succeed.
        c.init(address(this), address(this), address(this));

        // Create two proposals to allow some variability in proposalID selection.
        c.newGrantProposal(addr, amount);
        c.newAddressProposal(addr, "UTILS");

        // Determine a proposalID to operate on: map to 1 or 2.
        uint pid = 1 + (proposalIDOffset % 2);

        // Call voteProposal which may set proposal into finalising state (and sets votes).
        // We capture whether voteProposal reverts by try/catch.
        bool voteReverted;
        uint voteWeight;
        try c.voteProposal(pid) returns (uint w) {
            voteReverted = false;
            voteWeight = w;
        } catch {
            voteReverted = true;
            voteWeight = 0;
        }

        // Read current finalising flag and timeStart regardless of vote result.
        bool finalising = c.mapPID_finalising(pid);
        uint timeStart = c.mapPID_timeStart(pid);

        // If not finalising yet, try to force finalising by calling voteProposal again (best-effort).
        // Must be top-level calls that may change state.
        if (!finalising) {
            // Attempt another voteProposal; ignore revert by try/catch to continue.
            try c.voteProposal(pid) returns (uint w2) {
                voteReverted = false;
                voteWeight = w2;
            } catch {
                voteReverted = true;
            }
            finalising = c.mapPID_finalising(pid);
            timeStart = c.mapPID_timeStart(pid);
        }

        // If the proposal is finalising, simulate time passing by ensuring the coolOffPeriod has passed.
        // We cannot advance block.timestamp. But finaliseProposal requires (block.timestamp - timeStart) > coolOffPeriod.
        // To reach that branch without manipulating time, we can only call finaliseProposal and check two outcomes:
        // - it reverts due to time requirement, or - it succeeds and marks finalised. Our property concerns the success case.

        // Attempt finaliseProposal and record whether it reverted.
        bool finaliseReverted;
        try c.finaliseProposal(pid) {
            finaliseReverted = false;
        } catch {
            finaliseReverted = true;
        }

        // After attempting finaliseProposal, read visible post-state for the proposal.
        bool finalised = c.mapPID_finalised(pid);
        uint votesAfter = c.mapPID_votes(pid);

        // The asserted general rule: if finaliseProposal call did not revert, then the proposal must be marked finalised
        // and its votes must be reset to zero. We allow other cases (reverted) to be unconstrained.
        assert(finaliseReverted || (finalised == true && votesAfter == 0));
    }

    receive() external payable { }
}

