    // - addr: address used for recipient/proposedAddress
    // - amount: amount used for grant (ignored for address proposal)
    function run(bool isGrant, address addr, uint amount) public payable {
        require(addr != address(0)); // simple precondition to avoid trivial zero-address proposals

        // Initialize the contract c (fresh deployment assumption)
        c.init(address(this), address(this), address(this));

        // read proposalCount before creating
        uint before = c.proposalCount();

        // create one of the two kinds of proposals as top-level calls
        if (isGrant) {
            c.newGrantProposal(addr, amount);
        } else {
            c.newAddressProposal(addr, "UTILS");
        }

        // read proposalCount after creating
        uint after = c.proposalCount();

        // compute the id of the newly created proposal (should be before+1 if contract behaves)
        uint newPID = after; // expected new proposal id

        // read the stored type for the new proposal via public getter
        string memory storedType = c.mapPID_type(newPID);

        // General rule: creating a proposal increases proposalCount at least by 1 (after > before)
        // and the newly created proposal has a non-empty type string retrievable via the public getter.
        // (The assert uses comparisons and the retrieved string length check via bytes(...).length.)
        assert(after > before && bytes(storedType).length > 0);
    }

    receive() external payable { }
}

