        uint pid = c.proposalCount();
        // read stored grant recipient before voting via public getter for mapPID_grant: mapPID_grant has fields but only the mapping getter for struct is not autogenerated; however mapPID_grant is public so solidity generates a getter returning (address,uint)
        (address beforeRecipient, uint beforeAmount) = c.mapPID_grant(pid);

