        uint votesBefore = c.mapPID_votes(pid);

        // make some unrelated additional proposals if extraSteps>0 to vary state (call newAddressProposal)
        for (uint i = 0; i < extraSteps; i++) {
            // safe dummy call to create other proposals
            c.newAddressProposal(address(this), "DUMMY");
        }

        // attempt to vote; capture whether it reverts
        bool reverted;
        try c.voteProposal(pid) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe state after
        (address afterRecipient, uint afterAmount) = c.mapPID_grant(pid);
        uint votesAfter = c.mapPID_votes(pid);

        // General rule asserted:
        // - The stored grant recipient and amount for the proposal must remain equal to what was stored before the vote (voting should not mutate the proposal details).
        // - If the vote call did not revert, then votesAfter must be >= votesBefore (voteProposal may only increase or keep same mapPID_votes for that proposal when called by this member).
        assert(afterRecipient == beforeRecipient && afterAmount == beforeAmount && (reverted || votesAfter >= votesBefore));
    }

    receive() external payable {}
}

