        bool reverted;
        try c.voteProposal(pid) returns (uint w) { reverted = false; } catch { reverted = true; }
        // Read the grant details again
        (address storedRecipient2, uint storedAmount2) = c.mapPID_grant(pid);
        // General invariant: the stored recipient must remain equal and the stored amount must not exceed the originally proposed amount
        // Note: we compare storedAmount2 <= amount OR if initial storage somehow differed, ensure it did not increase compared to before vote
        bool amount_not_increased = (storedAmount2 <= amount) || (storedAmount2 <= storedAmount);
        assert(storedRecipient2 == storedRecipient && amount_not_increased);
    }
    receive() external payable {}
}

contract InvMutTest {
